const TALENTS: Array<[string, string]> = [["Pyromaniac", "Grants you 3 Potency (+5% of Intelligence)."], ["Amplification", "Reduces the cooldown of Arcane Blast by 2 seconds."], ["Ice Lance", "Casting a spell hurls an Ice Lance towards a random nearby enemy unit, dealing 20 (+50% Intelligence) Magical damage and Chilling the target hit for 4 seconds. Prioritizes non-Chilled targets."], ["Supernova", "If Arcane Blast targets an enemy above 90% health, gravity will collapse around it, dealing 50/100/150/200 Magical damage (+300% of Intelligence) to all nearby enemies. Has 10% chance to trigger on enemies at or below 90% health.\n\nValues scale with Arcane Blast level."], ["Ice Shards", "Increases the damage of Blizzard by 20% and its damage reduction by 30%."], ["Firestarter", "Allows Fire Bomb to trigger on enemies unaffected by Living Bomb and it deals 25% more damage."], ["Archmage", "Increases all Intelligence scalings by 35%, multiplicatively.\n\nOnly affects scalings of Mage Abilities and Talents."], ["Freezeburn", "Applying Living Bomb also Chills the target for 4 seconds. Applying Chill has 20% chance to apply Living Bomb, reduced to 8% against already Chilled targets. This effect cannot chain.\n\nLiving Bomb has to be learned for its debuff to be applied."], ["Lava Spawn", "While you control less than 10 Hydras, dealing damage from any source has 2% chance to spawn a Hydra that lasts half as long.\n\nHydra stats and effects can be found in the Customization Menu (F8)."], ["Burning Fury", "Hydras last for 4 additional seconds and their cleave now also triggers onto the primary target."], ["Frostbite", "Chilled enemies take 8% more damage, increased to 12% for Frozen enemies.\n\nApplying Chill on unaffected enemies Freezes them for 1,5 seconds."], ["Greater Pyroblast", "Increases the Intelligence scaling of Pyroblast by additional 2% and it now deals Magical damage, but will only fire while at or above 50 Cinderflame."], ["Overpowered", "You also benefit from all Spell Mastery effects, regardless of current Specialization."], ["Frostfire Bolt", "Arcane Blast also hurls a Frostfire Bolt at the target which deals 20 Magical damage (+90% of Intelligence). Each level of Living Bomb and Ring of Frost increase the damage dealt by 25.\n\nIf the target has Chill, deals 25% more damage and 15% of the damage to other nearby enemies. If the target has Living Bomb, deals 25% more damage and Freezes for 2 seconds. If the target has both debuffs, they’re consumed to fire another Frostfire Bolt after a 0,5 second delay."], ["Arcane Surge", "Arcane Blast’s Arcane effect now grants 2 Stacks per cast while below 3 Stacks and the maximum amount of stacks is increased to 8."], ["Blazing Soul", "Living Bomb now ticks 15% faster (+50% of Potency) and has additional 15% chance to burst."], ["Cold Splinters", "Whenever you Chill an enemy, you restore 0,5% of maximum mana and gain 2 Mastery, up to a maximum of 30 Mastery. Freezing triggers this effect at 200% effectiveness. Mastery bonus resets upon leaving combat."]];
const GLYPHS: Array<[string, string]> = [["Animosity", "Offensive Glyph\nGrants you 12% Critical Strike chance and increases the damage dealt by Critical Strikes by 15%."], ["Arc Striking", "Utility Glyph\nEach of your attacks reduces the remaining cooldown of your Q ability by 8% plus additional 0,25 seconds. Your Q spellcasts refund 40% of their mana cost."], ["Battle Frenzy", "Offensive Glyph\nGives your attacks 18% chance to grant you 32% Attack Speed for 5 seconds. Battle Frenzy must wear off before occuring again."], ["Blood Violence", "Offensive Glyph\nDealing damage from any source has 3% chance to cause the enemy flesh to explode, dealing 20 Attrition damage (+160% of Primary Attribute)."], ["Fortune", "Utility Glyph\nIncreases your Luck by additional 15%."], ["Fortitude", "Utility Glyph\nBoosts your Primary Attribute by 4 and additional 2 per Hero Level."], ["Glass Cannon", "Offensive Glyph\nMultiplicatively increases damage dealt from all sources by 15%, but all of your units take 10% more damage."], ["Hellfire", "Offensive Glyph\nDeals 3 damage and additional amount equal to 3 times your hero level to all enemy units within 400 range every 1,25 seconds. Damage dealt is modified based on the amount of targets hit:\n\n• 1 enemy: 200% damage\n• 2-3 enemies: 100% damage\n• 4+ enemies: 50% damage"], ["Mindhaste", "Utility Glyph\nIncreases your Haste by 7% and reduces the cooldown of all abilities by 0,2 seconds."], ["Supremacy", "Utility Glyph\nIncreases your Mastery by 20."], ["Thunder", "Offensive Glyph\nYour spellcasts have 18% chance to call down lightnings that deal 35 (+200% of Primary Attribute) to enemy units within 600 range."], ["Unsealed Power", "Offensive Glyph\nIncreases the damage dealt by Magical and Physical Type effects by 18%."]];

function GameText({ text }: { text: string }) {
  return (
    <Text size="small" style={{ whiteSpace: "pre-wrap" }}>
      {text}
    </Text>
  );
}

function notedName(name: string, stats: Array<[string, string]>): string {
  const row = stats.find(([label]) => label === name);
  return row ? `${name} — ${row[1]}` : name;
}

export default function MageSims() {
  const [mode, setMode] = useCanvasState<RunId>("mage-source", "mixed");
  const [place, setPlace] = useCanvasState("mage-place", 1);
  const [catalog, setCatalog] = useCanvasState<"all" | "picked">("mage-catalog", "picked");
  const list = RUNS[mode];
  const index = Math.min(Math.max(place, 1), list.length) - 1;
  const run = list[index];
  const talents = (catalog === "picked" ? TALENTS.filter((row) => run.talents.includes(row[0])) : TALENTS)
    .slice()
    .sort((a, b) => (TALENT_DPS[b[0]] ?? -1) - (TALENT_DPS[a[0]] ?? -1));
  const glyphs = (catalog === "picked" ? GLYPHS.filter((row) => run.glyphs.includes(row[0])) : GLYPHS)
    .slice()
    .sort((a, b) => (GLYPH_DPS[b[0]] ?? -1) - (GLYPH_DPS[a[0]] ?? -1));
  const rankedItems = run.items
    .map((row, itemIndex) => ({ row, code: run.codes[itemIndex] }))
    .sort((a, b) => (ITEM_DPS[b.code] ?? -1) - (ITEM_DPS[a.code] ?? -1));

  return (
    <Stack gap={20}>
      <Stack gap={6}>
        <H1>Arcane Mage, 5 целей</H1>
        <Text tone="secondary">
          Sunken City v2.5.2a · уровень 6 · 30 секунд · ожидаемый урон, без случайных бросков
        </Text>
      </Stack>

      <Row gap={8} wrap>
        <Pill active={mode === "mixed"} onClick={() => setMode("mixed")}>Shop + drop</Pill>
        <Pill active={mode === "shop"} onClick={() => setMode("shop")}>Только Shop Item</Pill>
        <Pill active={mode === "drop"} onClick={() => setMode("drop")}>Только Random drop</Pill>
      </Row>
      <Row gap={8} wrap>
        {list.map((_row, itemIndex) => (
          <Pill key={itemIndex + 1} active={index === itemIndex} onClick={() => setPlace(itemIndex + 1)}>
            {String(itemIndex + 1)}
          </Pill>
        ))}
      </Row>

      <Grid columns={5} gap={16}>
        <Stat value={run.dps} label="DPS" tone="success" />
        <Stat value={run.total} label="Урон за 30 с" />
        <Stat value={run.crit} label="Крит" />
        <Stat value={run.intel} label="Интеллект" />
        <Stat value={run.manaLeft} label="Мана в конце" />
      </Grid>

      <H2>Урон по источникам</H2>
      <BarChart
        horizontal
        height={260}
        categories={run.sources.map((row) => row[0])}
        series={[{ name: "DPS", data: run.sources.map((row) => row[1]), tone: "info" }]}
        valueSuffix=" DPS"
        showValues
      />
      <Text size="small" tone="tertiary">
        Ожидаемый урон источника за 30 с, делённый на 30. Броня манекена 15. Три куска одного прогона Arcane, пул top 80, 5 целей.
      </Text>

      <H2>Порядок кнопок</H2>
      <Table
        headers={["Секунда", "Заклинание"]}
        columnAlign={["right", "left"]}
        rows={run.actions}
      />
      <Text size="small" tone="tertiary">
        Каст 0,15 с до эффекта, затем ещё 0,30 с герой занят. Living Bomb обновляется, если дот спадёт в ближайшую секунду.
      </Text>

      <H2>Характеристики в бою</H2>
      <Table
        headers={["Параметр", "Значение"]}
        rows={run.stats}
      />

      <Divider />

      <H2>Предметы в связке</H2>
      <Text tone="secondary">
        {LABELS[mode]}. Место {index + 1}. Arcane. 5 целей. Очки навыков: {run.points}.
      </Text>
      <Table
        headers={["Предмет", "Источник", "Описание из игры"]}
        rows={rankedItems.map(({ row }) => [
          notedName(row[0], run.stats),
          row[1],
          <GameText text={row[2]} />,
        ])}
        striped
        rowTone={rankedItems.map(() => "success" as const)}
      />

      <Row gap={8} align="center">
        <H2>Таланты и глифы</H2>
        <Pill active={catalog === "picked"} onClick={() => setCatalog("picked")}>
          В связке
        </Pill>
        <Pill active={catalog === "all"} onClick={() => setCatalog("all")}>
          Все прогнанные
        </Pill>
      </Row>
      <Text size="small" tone="tertiary">
        Таланты и глифы считались, если DPS шестёрки без них входил в топ-10 своей категории. Сортировка по однослотовому DPS Arcane.
      </Text>

      <H3>Таланты</H3>
      <Table
        headers={["Талант", "Описание из игры"]}
        rows={talents.map(([name, tip]) => [name, <GameText text={tip} />])}
        striped
        stickyHeader
        rowTone={talents.map((row) => (run.talents.includes(row[0]) ? "success" : undefined))}
      />

      <H3>Глифы</H3>
      <Table
        headers={["Глиф", "Описание из игры"]}
        rows={glyphs.map(([name, tip]) => [name, <GameText text={tip} />])}
        striped
        stickyHeader
        rowTone={glyphs.map((row) => (run.glyphs.includes(row[0]) ? "success" : undefined))}
      />

      <Callout tone="neutral" title="Прогон">
        Arcane, 5 целей, топ-80 предметов. Shop + drop — общий топ. Только Shop Item и только Random drop — свои топы. Связки лавки с дропом остаются в общем топе и отдельным списком не показаны.
      </Callout>
    </Stack>
  );
}
